import argparse
import importlib

import numpy as np
import pandas as pd

import config
from data_loading import load_series
from metrics import dense_metrics, wandb_start, wandb_log_subject, wandb_finish
from sklearn.metrics import confusion_matrix

MODEL_MODULES = {"logreg_csp": "models.logreg_csp", "light_tcn": "models.light_tcn"} # this will change


def evaluate(model_name, subject):
    module = importlib.import_module(MODEL_MODULES[model_name])    # imports only what is needed
    preds, info = module.run(subject, config.TRAIN_SERIES, config.VAL_SERIES)

    y_true = np.concatenate([load_series(subject, s)[1].T for s in config.VAL_SERIES])
    y_score = np.concatenate([preds[s] for s in config.VAL_SERIES])
    assert y_true.shape == y_score.shape, (y_true.shape, y_score.shape)
    return dense_metrics(y_true, y_score), info, preds

